import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/app.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        username TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key) VALUES ('admin', 'admin@corp.io', 'admin', 'sk-admin-9f8e7d6c')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key) VALUES ('alice', 'alice@corp.io', 'user', 'sk-alice-1a2b3c4d')")
    db.commit()
    db.close()

@app.before_request
def authenticate():
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'Missing API key'}), 401
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
    if not user:
        return jsonify({'error': 'Invalid API key'}), 403
    g.current_user = dict(user)

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': f'Invalid field. Allowed: {allowed_fields}'}), 400

    # Log the search action
    db = get_db()
    db.execute(
        "INSERT INTO audit_log (action, username) VALUES (?, ?)",
        (f"search:{field}={value}", g.current_user['username'])
    )
    db.commit()

    # Build query with validated field name but user-controlled value
    query = f"SELECT username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        results = db.execute(query).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/me', methods=['GET'])
def get_current_user():
    return jsonify({
        'username': g.current_user['username'],
        'email': g.current_user['email'],
        'role': g.current_user['role']
    })

@app.route('/api/admin/users', methods=['GET'])
def list_all_users():
    if g.current_user['role'] != 'admin':
        return jsonify({'error': 'Admin access required'}), 403
    db = get_db()
    users = db.execute('SELECT username, email, role FROM users').fetchall()
    return jsonify({'users': [dict(u) for u in users]})

@app.route('/api/admin/grant', methods=['POST'])
def grant_role():
    if g.current_user['role'] != 'admin':
        return jsonify({'error': 'Admin access required'}), 403
    data = request.get_json()
    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE username = ?', (data['role'], data['username']))
    db.commit()
    return jsonify({'status': 'updated'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
